def solve(N, K, M):
    MOD = 10**9 + 9
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    dp[0][0] = 1
    for i in range(1, N + 1):
        for w in range(K + 1):
            for x in range(1, i + 2):
                dp[i][w] = (dp[i][w] + dp[i - x][w + 1]) % MOD

    result = 0
    for k in range(K + 1):
        result = (result + dp[N][k] * (k + 1)) % MOD

    return result

