from math import sqrt
from itertools import product

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def find_numbers_with_factors(target, factors, primes):
    filtered_numbers = [num for num in primes if target % num == 0]
    for num in filtered_numbers:
        count = 0
        while target % num == 0:
            target //= num
            count += 1
        if factors[count]:
            factors[count].append(num)
    return target <= 1, factors

def is_friendly(suitable_sequence):
    factors_counts = {}
    for factor in suitable_sequence:
        if factor in factors_counts:
            factors_counts[factor] += 1
        else:
            factors_counts[factor] = 1
    return len(factors_counts) <= len(suitable_sequence)

def is_ideal(numbers):
    for combination in product(numbers, repeat=len(numbers)):
        suitable = []
        for i in range(len(combination)):
            for j in range(len(combination)):
                if combination[j] % combination[i] == 0:
                    suitable.append(combination[j])
        if is_friendly(suitable):
            return True
    return False

def find_ideal_sequence(n, k, numbers):
    primes = list(filter(is_prime, numbers))
    minimum_factors = [1 for _ in range(k)]
    for i, number in enumerate(numbers):
        for prime in primes:
            if is_prime(prime) and number % prime == 0:
                _, numbers_remaining = find_numbers_with_factors(number, minimum_factors, primes)
                if numbers_remaining:
                    minimum_factors[i] += numbers_remaining[prime]
    return minimum_factors

