def get_divisors(n, root_size=1000):
    """By default, we include the root_size as well. The main idea is to expand from it."""
    assert n == 2**(root_size-1) + 1
    if root_size < 3:
        root_size = 3
    assert 3 <= root_size, "Do not consider getting below 3."
    more, divisors = 1, []
    for scale in range(2, root_size):
