def count_factorial(n):
    if n == 1:
        return 1

    if n % 10 == 0:
        return 1

    factorial = 1
    for i in range(2, n + 1):
        factorial *= i

    return factorial

def nth_fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def is_strange_number(n):
    if n % 10 == 1 or n % 10 == 2:
        return True
    return False

def solve(question):
    l, r, k = question
    if k == 1:
        if r - l + 1 <= question:
            return r - l + 1
    elif k == 2:
        return (r - l + 1) * (r - l + 2) // 2
    elif k == 3:
        return is_strange_number(r * r - l * l + 2 * (r - l + 1))
    elif k == 4:
        return nth_fibonacci(r * r - l * l)
    elif k == 5:
        return count_factorial(r - l + 1)

