import sys

def floyd_warshall(G):
    n = len(G)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if G[i][k] + G[k][j] < G[i][j]:
                    G[i][j] = G[k][j]

    return G

def is_cycle(v, G):
    n = len(G)

    for i in range(n):
        for j in range(1, n):
            if G[v][i] + G[i][j] >= n:
                continue

            current = i

            for _ in range(1, n//2 + 1):
                current += 1
                if G[v][i] + G[i][current] < G[v][current] + G[v][i]:
                    return True, i, current

    return False, 0, 0

def solve(N, M, Q, edges, days):
    G = [[float('inf') for _ in range(N+1)] for _ in range(N+1)]

    for a, b in edges:
        G[a][b] = 1
        G[b][a] = 1

    for day in range(Q):
        temp = floyd_warshall(G)

        result = ["NO"] * Q

        for v in range(1, N+1):
            ok, cycle_i, cycle_j = is_cycle(v, temp)

            if cycle_i != cycle_j:
                continue

            if ok and len(set([v, cycle_i, cycle_j])) == 3:
                result[day] = "YES"

        print(result[day])

