    mod = 10 ** 9 + 7
    cache = {}

    def meeting(a, sum1):
        if a == list(range(n)):
            return [0, sum1]
        d = (a + k) % n
        if (a, sum1, d) in cache:
            return cache[(a, sum1, d)]
        best = [-1]
        for i in range(min(a, sum1), max(a, sum1), k):
            cur = max(meeting(a + 1, sum1 - i) + [i], meeting([], i))
            best = min(best, cur)
        best = [min(best, [0] + i) for i in best]
        cache[(a, sum1, d)] = best[-1]
        return best[-1]

