from collections import Counter

def is_ideal_sequence(sequence):
    sequence_freq = Counter(sequence)
    unique_elements = len(sequence)
    distinct_element_count = len(set(sequence_freq.keys()))
    return len(sequence_freq) == len(set(sequence_freq.keys()))

def find_ideal_sequence(k, numbers):
    numbers_count = len(set(numbers))
    if numbers_count > k:
        return 0

    optimal_k = -1
    optimal_sequence = None

    for start in range(len(numbers) - k + 1):
        count = Counter(numbers[start:start+k])
        has_unique_elements = len(count) > 2

        if optimize_solution(start, count, has_unique_elements, numbers_count, k, optimal_k, optimal_sequence):
            optimal_k = k
            optimal_sequence = count

    sequence_set = set()
    if optimal_k > 0:
        for number_count in optimal_sequence.items():
            for i in range(2, number_count[0] + 1):
                sequence_set.add(number_count[1] * (i**14))

    if not any(number in sequence_set for number in numbers):
        return optimal_k, list(optimal_sequence.keys())
    else:
        return 0

def optimize_solution(start, current_count, has_unique_elements, numbers_count, k, optimal_k, optimal_sequence):
    current_uniques = current_count.size()
    diff = k - optimal_k
    if diff == 0:
        return has_unique_elements and optimal_k > 1

    if diff < 0:
        return False

    if diff > 0:
        potential = list(current_count.keys())
        for potential_key in potential:
            latest_key = current_count[potential_key]
            for probable_optimal_key in list(current_count.keys()):
                if probable_optimal_key > potential_key and current_count[probable_optimal_key] < latest_key:
                    return False

    minimum_additional_put = numbers_count - has_unique_elements
    additional_put = (k - current_uniques) - len(set(current_count.keys()))

    return optimal_k < k and minimum_additional_put <= additional_put

def main():
    import sys
    input_lines = iter(sys.stdin.readline, "")
    n, k = map(int, next(input_lines).strip().split())

    numbers = list(map(int, next(input_lines).strip().split()))

    result = find_ideal_sequence(n, k, numbers)
    if result != 0:
        print(f'{result} {' '.join(str(number) for number in result)}')
    else:
        print(0)

