def kth_interesting_integer(n, t):
    if t == 1:
        return hex(n)[2:]  # n is hex, 2nd part is decimal

    k = abs(n)
    t = t - 1
    new_t = t

    while k > 1:
        remainder = k % 16
        k = k // 16

        if remainder <= new_t:
            num = 3 if remainder == 10 else remainder
        else:
            num = 3 + new_t - remainder

        new_t -= 1
        k += 16 ** t - 1

    if k == 3 and new_t > 1:
        return hex(n)[2:] + '42'
    else:
        return hex(n)[2:] + str(num)

