import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_all_primes(n):
    is_prime_list = [True] * (n+1)
    is_prime_list[0], is_prime_list[1] = False, False
    for p in range(2, int(math.sqrt(n))):
        if is_prime_list[p]:
            for i in range(p * p, n+1, p):
                is_prime_list[i] = False
    return [i for i in range(n+1) if is_prime_list[i]]

def find_ideal_sequence(x_vals):
    n = len(x_vals)
    if n < k:
        return 0
    primes = find_all_primes(1000000000)
    x_vals.sort()
    p_map = {}
    for i in range(1, k+1):
        x = x_vals[i-1]
        for j in range(len(primes)):
            if x % primes[j] == 0 and primes[j] not in p_map:
                p_map[primes[j]] = x
                break
    if not p_map:
        return 0
    common_primes = list(p_map.keys())
    sequence = [p_map[common_primes[-1]]]
    while len(sequence) < k:
        next_seq_item = min([x_map[pr] * (i - 1) for pr, x_map in p_map.items()], key=lambda x: x[1])
        sequence.append(next_seq_item)
    return sequence

