from itertools import chain, combinations

def powerset(iterable, r):
    s = list(iterable)
    return chain.from_iterable(combinations(s, r))

def average_list(arr):
    return sum(arr) / len(arr)

def solve(N, K, M):
    MOD = M
    results = [0] * (N + 1)
    for p in powerset(range(1, N + 1), K):
        average = sum(p) / len(p)
        if average.is_integer():
            k = int(average)
            if 0 <= k <= K:
                index = k * (N + 1)
                current_results = results[index]
                for i in range(1, N + 1):
                    if p.count(i) > 0:
                        current_results += 1
                results[index] = (current_results) % MOD
    return results

