from fractions import Fraction

# Miller-Rabin primality test
def is_prime(n, k=5):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if not n % 2:
        return False
    r, d = 0, n - 1
    while not d % 2:
        r += 1
        d //= 2
    for _ in range(k):
        a = 2 + n % 2**(r+1)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(1, r):
            x = (x * x) % n
            if x == 1:
                return False
            if x == n - 1:
                break
        else:
            return False
    return True

def find_number_of_multisets(N, K, M):
    # If M is prime, use Legendre's formula to count the Euler phi function
    non_zero = N - 1
    if M != 1:
        non_zero *= (M - 1)
    result = 1
    for i in range(1, K + 1):
        result = result * non_zero % M
        non_zero -= i
    return result % M

